/// <summary>
/// Formula for FromSlot
/// </summary>
/// <returns>String</returns>
public static server str getFromSlot()
{
    str recId = SysComputedColumn::returnField(tablestr(METSlotTableView), dataEntityDataSourceStr(METSlotTableView, METSlotTable), fieldStr(METSlotTable, RecId));

    str expression = "SELECT CASE WHEN Type = 0 THEN COALESCE(SUBSTRING(REPLACE(FromSlot, '-', ''), 1, 3), '') WHEN Type IN (1, 2, 3, 4) THEN COALESCE(SUBSTRING(REPLACE(FromSlot, '-', ''), 1, 2), '') ELSE '' END AS FromSlotSubstring FROM METSlotTable where RECID =" + recId;

    return expression;
}

/// <summary>
/// Formula for ToSlot
/// </summary>
/// <returns>String</returns>
public static server str getToSlot()
{
    str recId = SysComputedColumn::returnField(tablestr(METSlotTableView), dataEntityDataSourceStr(METSlotTableView, METSlotTable), fieldStr(METSlotTable, RecId));

    str expression = "SELECT CASE WHEN Type = 0 THEN COALESCE(SUBSTRING(REPLACE(ToSlot, '-', ''), 1, 3), '') WHEN Type IN (1, 2, 3, 4) THEN COALESCE(SUBSTRING(REPLACE(ToSlot, '-', ''), 1, 2), '') ELSE '' END AS FromSlotSubstring FROM METSlotTable where RECID =" + recId;

    return expression;
}
